// pyrepr.mjs — Python-compatible repr()/print() formatting helpers.
//
// Reimplements the subset of CPython's object repr semantics needed to make
// console.log output byte-identical with Python's print(): string repr with
// quote selection and escaping, list repr, dict-style repr, and a dispatch
// helper used by the entry script.

// Code points Python's str.isprintable() reports as non-printable for the
// ranges we can encounter (categories Cc, Cf, Cs, Co, Zl, Zp, Zs minus the
// ASCII space). U+00A0 .. U+00FF handled individually below.
const NON_PRINTABLE_RANGES = [
  [0x0000, 0x001f], // C0 controls
  [0x007f, 0x00a0], // DEL, C1 controls, NBSP (Zs)
  [0x00ad, 0x00ad], // soft hyphen (Cf)
  [0x0600, 0x0605], [0x061c, 0x061c], [0x06dd, 0x06dd], [0x070f, 0x070f],
  [0x0890, 0x0891], [0x08e2, 0x08e2],
  [0x1680, 0x1680], // ogham space mark (Zs)
  [0x180e, 0x180e], // mongolian vowel separator (Cf)
  [0x2000, 0x200f], // en quad .. zero-width joiner (Zs/Cf)
  [0x2028, 0x202e], // line/para separators (Zl/Zp) + bidi controls (Cf)
  [0x205f, 0x2064], // math space (Zs) + invisible operators (Cf)
  [0x2066, 0x206f], // bidi isolates + deprecated formatting (Cf)
  [0x3000, 0x3000], // ideographic space (Zs)
  [0xd800, 0xdfff], // surrogates (Cs)
  [0xe000, 0xf8ff], // private use (Co)
  [0xfeff, 0xfeff], // BOM / zero-width no-break space (Cf)
  [0xfff9, 0xfffb], // interlinear annotation (Cf)
  [0x110bd, 0x110bd], [0x110cd, 0x110cd],
  [0x13430, 0x1343f],
  [0x1bca0, 0x1bca3], [0x1d173, 0x1d17a],
  [0xe0000, 0xe0fff], // tags + variation selectors supplement (Cf)
  [0xf0000, 0xffffd], [0x100000, 0x10fffd], // plane 15/16 private use (Co)
];

export function isPrintable(cp) {
  if (cp === 0x20) return true; // ASCII space is printable
  for (const [lo, hi] of NON_PRINTABLE_RANGES) {
    if (cp < lo) return true;
    if (cp <= hi) return false;
  }
  return true;
}

function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Mirrors CPython's unicode_repr(): single quotes by default; double quotes
// only when the string contains a single quote and no double quote.
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\' || ch === quote) {
      out += '\\' + ch;
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (!isPrintable(cp)) {
      out += escapeCodePoint(cp);
    } else {
      out += ch;
    }
  }
  return out + quote;
}

// Dispatch repr: strings, numbers (int-valued), arrays (Python list),
// FrozenDict-like objects exposing __pyRepr__().
export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (typeof value === 'number') return String(value);
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (value === null || value === undefined) return 'None';
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  if (typeof value.__pyRepr__ === 'function') return value.__pyRepr__();
  return String(value);
}

// Python len() counts Unicode code points, not UTF-16 units.
export function pyLen(s) {
  return typeof s === 'string' ? Array.from(s).length : s.length;
}

