const result5 = under2camel(result4); // 转换回来
print(result5);
const result6 = slugify(strings[strings.length - 1]); // 最后一个的slug
print(result6);
const result7 = unit_len(strings, 'string'); // 长度描述
print(result7);
const result8 = cardinalize('string', strings.length); // 复数形式
print(result8);
