const result18 = new FrozenDict([...mapping].map(([k, v]) => [k, pyLen(v)])); // 长度映射
print(result18);
const result19 = new FrozenDict([...mapping].map(([k, v]) => [k.toUpperCase(), v])); // 大写键映射
print(result19);
const result20 = new FrozenDict([...mapping].map(([k, v]) => [k, slugify(v)])); // slug值映射
print(result20);

