cd /tmp && node -e '
const chars = "abcXYZ019 _-!@#.\x27\"\\:,;~àüß中🙂\t";
const lines = [];
let seed = 42;
const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
for (let i = 0; i < 60; i++) {
  const n = 1 + Math.floor(rnd() * 4);
  const parts = [];
  for (let j = 0; j < n; j++) {
    let s = "";
    const len = Math.floor(rnd() * 8);
    for (let k = 0; k < len; k++) s += chars[Math.floor(rnd() * chars.length)];
    parts.push(s);
  }
  lines.push(parts.join(","));
}
require("fs").writeFileSync("fuzz.txt", lines.join("\n") + "\n");
'
