  diff -q exp.txt got.txt > /dev/null || { echo "MISMATCH: <<$line>>"; diff exp.txt got.txt | head -6; fail=1; }
done < fuzz.txt
[ $fail -eq 0 ] && echo "FUZZ: ALL 60 RANDOM CASES MATCH"

